 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    row_bars = [r for r in range(h) if all(v == 2 for v in grid[r])]
    col_bars = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    if row_bars:
        axis, bar = 0, row_bars[0]
    elif col_bars:
        axis, bar = 1, col_bars[0]
    else:
        return [row[:] for row in grid]

    non_bar = [grid[r][c] for r in range(h) for c in range(w)
               if (r != bar if axis == 0 else c != bar)]
    bg = max(set(non_bar), key=non_bar.count)
    coords = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if (r != bar if axis == 0 else c != bar)
              and grid[r][c] not in (bg, 2, 8)]
    if not coords:
        return [row[:] for row in grid]

    vals = [r if axis == 0 else c for r, c, _ in coords]
    lo, hi = min(vals), max(vals)
    size = h if axis == 0 else w
    if hi < bar:
        shift = bar - 1 - hi
        stripe = lo + shift - 1
    else:
        shift = bar + 1 - lo
        stripe = hi + shift + 1

    out = [row[:] for row in grid]
    for r, c, _ in coords:
        out[r][c] = bg
    for r, c, v in coords:
        rr, cc = (r + shift, c) if axis == 0 else (r, c + shift)
        if 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = v
    if 0 <= stripe < size:
        if axis == 0:
            out[stripe] = [8] * w
        else:
            for r in range(h):
                out[r][stripe] = 8
    return out


